// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.VF;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.assertEvaluationError;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.date;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.decimal;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dt;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dts;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dur;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.integer;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.str;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.time;

import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

/**
 * Edge cases of {@code dtf:makeDate}, {@code dtf:age} and {@code dtf:atTimeZone}.
 */
class MakeDateAgeAtTimeZoneEdgeCaseTest {

	private final MakeDate makeDate = new MakeDate();
	private final Age age = new Age();
	private final AtTimeZone atTimeZone = new AtTimeZone();

	// makeDate(y, m, d)

	@ParameterizedTest
	@CsvSource({ "2024, 13, 1", "2024, 0, 1", "2024, 1, 0", "2024, 4, 31", "2024, 1, 32", "2024, -1, 1",
			"2024, 1, -1" })
	void impossibleDatesAreAnEvaluationError(int year, int month, int day) {
		assertEvaluationError(year + "-" + month + "-" + day,
				() -> makeDate.evaluate(VF, integer(year), integer(month), integer(day)));
	}

	@Test
	void negativeZeroAndFiveDigitYearsAreFormattedCanonically() {
		assertThat(makeDate.evaluate(VF, integer(-44), integer(3), integer(15))).isEqualTo(date("-0044-03-15"));
		assertThat(makeDate.evaluate(VF, integer(0), integer(1), integer(1))).isEqualTo(date("0000-01-01"));
		assertThat(makeDate.evaluate(VF, integer(10000), integer(1), integer(1))).isEqualTo(date("10000-01-01"));
		assertThat(makeDate.evaluate(VF, integer(1), integer(1), integer(1))).isEqualTo(date("0001-01-01"));
	}

	@Test
	void nonIntegerComponentsAreAnEvaluationError() {
		// pins current behaviour: only integer-typed literals are accepted, decimals and doubles with an integral
		// value are rejected rather than narrowed
		assertEvaluationError("decimal year",
				() -> makeDate.evaluate(VF, decimal("2024.0"), integer(2), integer(29)));
		assertEvaluationError("double day",
				() -> makeDate.evaluate(VF, integer(2024), integer(2), VF.createLiteral(29.0d)));
		assertEvaluationError("string year",
				() -> makeDate.evaluate(VF, VF.createLiteral("2024", CoreDatatype.XSD.STRING), integer(2),
						integer(29)));
		// derived integer types are integers
		assertThat(makeDate.evaluate(VF, VF.createLiteral(2024), VF.createLiteral((short) 2),
				VF.createLiteral(29L))).isEqualTo(date("2024-02-29"));
	}

	@Test
	void resultIsAnXsdDateWithoutTimezone() {
		Literal result = makeDate.evaluate(VF, integer(2024), integer(5), integer(17));
		assertThat(result.getDatatype()).isEqualTo(CoreDatatype.XSD.DATE.getIri());
		assertThat(result.getLabel()).isEqualTo("2024-05-17");
	}

	// age(later, earlier)

	@Test
	void resultIsAnXsdDurationWithCalendarComponents() {
		Literal result = age.evaluate(VF, date("2024-03-04"), date("2023-01-01"));
		assertThat(result).isEqualTo(dur("P1Y2M3D"));
		assertThat(result.getDatatype()).isEqualTo(CoreDatatype.XSD.DURATION.getIri());
	}

	@Test
	void laterBeforeEarlierGivesANegativeDuration() {
		assertThat(age.evaluate(VF, date("2023-01-01"), date("2024-03-04"))).isEqualTo(dur("-P1Y2M3D"));
		assertThat(age.evaluate(VF, dt("2024-01-01T00:00:00"), dt("2024-01-01T00:00:01"))).isEqualTo(dur("-PT1S"));
	}

	@Test
	void februaryTwentyNinthAnniversaries() {
		// pins current behaviour (java.time Period semantics): Feb 29 -> Feb 28 of the next year is 11 months and
		// 30 days, not a full year; Feb 29 -> Mar 1 of the next year is one year and one day
		assertThat(age.evaluate(VF, date("2025-02-28"), date("2024-02-29"))).isEqualTo(dur("P11M30D"));
		assertThat(age.evaluate(VF, date("2025-03-01"), date("2024-02-29"))).isEqualTo(dur("P1Y1D"));
		assertThat(age.evaluate(VF, date("2028-02-29"), date("2024-02-29"))).isEqualTo(dur("P4Y"));
	}

	@Test
	void dateTimeInputsIncludeTimeComponents() {
		assertThat(age.evaluate(VF, dt("2024-01-02T03:04:05"), dt("2024-01-01T00:00:00")))
				.isEqualTo(dur("P1DT3H4M5S"));
		// the time part borrows a day when it is negative
		assertThat(age.evaluate(VF, dt("2024-01-02T00:00:00"), dt("2024-01-01T23:00:00"))).isEqualTo(dur("PT1H"));
		assertThat(age.evaluate(VF, dt("2024-03-01T00:00:00"), dt("2024-02-28T12:00:00"))).isEqualTo(dur("P1DT12H"));
	}

	@Test
	void mixedDateAndDateTimeTreatsTheDateAsMidnight() {
		// pins current behaviour: an xsd:date is midnight, so no error is raised
		assertThat(age.evaluate(VF, dt("2024-01-01T06:00:00"), date("2024-01-01"))).isEqualTo(dur("PT6H"));
		assertThat(age.evaluate(VF, date("2024-01-02"), dt("2024-01-01T18:00:00"))).isEqualTo(dur("PT6H"));
	}

	@Test
	void mixedTimezonesAreAlignedToTheFirstArgument() {
		// pins current behaviour: both values are moved to the offset of `later` before the components are computed
		assertThat(age.evaluate(VF, dt("2024-01-01T00:00:00+01:00"), dt("2024-01-01T00:00:00Z")))
				.isEqualTo(dur("-PT1H"));
		assertThat(age.evaluate(VF, dt("2024-01-01T00:00:00Z"), dt("2024-01-01T00:00:00+01:00")))
				.isEqualTo(dur("PT1H"));
		// a value without timezone is UTC when the other one has a timezone
		assertThat(age.evaluate(VF, dt("2024-01-01T02:00:00+01:00"), dt("2024-01-01T00:00:00")))
				.isEqualTo(dur("PT1H"));
	}

	// atTimeZone(dt, zone)

	@ParameterizedTest
	@CsvSource({ "Europe/Oslo, 2024-01-01T13:00:00+01:00", "+00:00, 2024-01-01T12:00:00Z",
			"+05:30, 2024-01-01T17:30:00+05:30", "UTC, 2024-01-01T12:00:00Z", "Z, 2024-01-01T12:00:00Z",
			"GMT, 2024-01-01T12:00:00Z", "-08:00, 2024-01-01T04:00:00-08:00",
			"America/New_York, 2024-01-01T07:00:00-05:00" })
	void regionIdsOffsetsAndUtcSpellingsAreAccepted(String zone, String expected) {
		assertThat(atTimeZone.evaluate(VF, dt("2024-01-01T12:00:00Z"), str(zone))).isEqualTo(dt(expected));
	}

	@Test
	void unknownZonesAreAnEvaluationError() {
		for (String zone : List.of("Not/AZone", "+25:00", "", "Oslo", "CEST+1")) {
			assertEvaluationError(zone, () -> atTimeZone.evaluate(VF, dt("2024-01-01T12:00:00Z"), str(zone)));
		}
	}

	@Test
	void inputWithoutTimezoneIsInterpretedAsLocalTimeInTheZone() {
		// pins current behaviour (and the class Javadoc): a value without timezone is wall-clock time in `zone`,
		// so the clock value is kept and the zone's offset is attached; it is not treated as UTC
		assertThat(atTimeZone.evaluate(VF, dt("2024-07-01T12:00:00"), str("Europe/Oslo")))
				.isEqualTo(dt("2024-07-01T12:00:00+02:00"));
		assertThat(atTimeZone.evaluate(VF, dt("2024-07-01T12:00:00"), str("+05:30")))
				.isEqualTo(dt("2024-07-01T12:00:00+05:30"));
		// the user documentation only states that the result carries the offset of the requested zone
		assertThat(atTimeZone.evaluate(VF, dt("2024-07-01T12:00:00"), str("UTC")))
				.isEqualTo(dt("2024-07-01T12:00:00Z"));
	}

	@Test
	void daylightSavingGapAndOverlapInOslo() {
		// pins current behaviour (java.time ZonedDateTime.of): a local time in the spring-forward gap is shifted
		// forward by the length of the gap; a local time in the autumn overlap takes the earlier (summer) offset
		assertThat(atTimeZone.evaluate(VF, dt("2024-03-31T02:30:00"), str("Europe/Oslo")))
				.isEqualTo(dt("2024-03-31T03:30:00+02:00"));
		assertThat(atTimeZone.evaluate(VF, dt("2024-10-27T02:30:00"), str("Europe/Oslo")))
				.isEqualTo(dt("2024-10-27T02:30:00+02:00"));
		// instants on either side of the gap convert unambiguously
		assertThat(atTimeZone.evaluate(VF, dt("2024-03-31T00:59:59Z"), str("Europe/Oslo")))
				.isEqualTo(dt("2024-03-31T01:59:59+01:00"));
		assertThat(atTimeZone.evaluate(VF, dt("2024-03-31T01:00:00Z"), str("Europe/Oslo")))
				.isEqualTo(dt("2024-03-31T03:00:00+02:00"));
	}

	@Test
	void timeInputGivesTimeWithOffsetAndDateInputGivesMidnightDateTime() {
		assertThat(atTimeZone.evaluate(VF, time("10:00:00"), str("+05:30"))).isEqualTo(time("10:00:00+05:30"));
		assertThat(atTimeZone.evaluate(VF, time("10:00:00Z"), str("+05:30"))).isEqualTo(time("15:30:00+05:30"));
		assertThat(atTimeZone.evaluate(VF, time("23:30:00Z"), str("+05:30"))).isEqualTo(time("05:00:00+05:30"));
		// pins current behaviour (class Javadoc: "dates become midnight dateTimes"): an xsd:date is not an error
		assertThat(atTimeZone.evaluate(VF, date("2024-07-01"), str("Europe/Oslo")))
				.isEqualTo(dt("2024-07-01T00:00:00+02:00"));
		assertThat(atTimeZone.evaluate(VF, date("2024-07-01Z"), str("Europe/Oslo")))
				.isEqualTo(dt("2024-07-01T02:00:00+02:00"));
	}

	@Test
	void dateTimeStampInputGivesAnXsdDateTimeResult() {
		// per the user documentation: atTimeZone "returns an xsd:dateTime (or xsd:time for a time input)"
		Literal result = atTimeZone.evaluate(VF, dts("2024-07-01T12:00:00Z"), str("Europe/Oslo"));
		assertThat(result.getDatatype()).isEqualTo(CoreDatatype.XSD.DATETIME.getIri());
		assertThat(result).isEqualTo(dt("2024-07-01T14:00:00+02:00"));
	}
}
